#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <vector>
#include "allheaders.h"

static void send_to_devnull(const char *) {}
static void leptSetStdNullHandler() { leptSetStderrHandler(send_to_devnull); }

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 1; }
    FILE *f = fopen(argv[1], "rb");
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::vector<uint8_t> data(sz);
    fread(data.data(), 1, sz, f);
    fclose(f);

    BOX *box;
    PIX *pixs, *pixd;
    PIX *pix1, *pix2, *pix3, *pix4, *pix5, *pix6, *pix7, *pix8;
    PIXCMAP *cmap;

    leptSetStdNullHandler();
    pixs = pixReadMemSpix(data.data(), data.size());
    if(pixs==NULL) { printf("pixs NULL\n"); return 0; }
    int w,h,d;
    pixGetDimensions(pixs, &w, &h, &d);
    printf("pixs: %dx%d depth=%d\n", w, h, d);

    pix1 = pixThresholdTo4bpp(pixs, 6, 1);
    pixGetDimensions(pix1, &w, &h, &d);
    printf("pix1: %dx%d depth=%d cmap=%d\n", w, h, d, pixGetColormap(pix1)!=NULL);
    box = boxCreate(120, 30, 200, 200);
    pixColorGray(pix1, box, L_PAINT_DARK, 220, 0, 0, 255);
    boxDestroy(&box);
    pixGetDimensions(pix1, &w, &h, &d);
    printf("pix1 after color: %dx%d depth=%d cmap=%d\n", w, h, d, pixGetColormap(pix1)!=NULL);
    if (pixGetColormap(pix1)) {
        PIXCMAP *c = pixGetColormap(pix1);
        printf("  cmap count: %d\n", pixcmapGetCount(c));
    }

    pix2 = pixScale(pix1, 1.5, 1.5);
    pixGetDimensions(pix2, &w, &h, &d);
    printf("pix2: %dx%d depth=%d\n", w, h, d);

    cmap = pixGetColormap(pix1);
    pix3 = pixOctcubeQuantFromCmap(pix2, cmap, 4, 3, L_EUCLIDEAN_DISTANCE);
    pixGetDimensions(pix3, &w, &h, &d);
    printf("pix3: %dx%d depth=%d\n", w, h, d);

    pix4 = pixConvertTo32(pix3);
    pixGetDimensions(pix4, &w, &h, &d);
    printf("pix4: %dx%d depth=%d\n", w, h, d);

    // Check colors in pix4
    PIX *pixc = pixFewColorsOctcubeQuant1(pix4, 3);
    if (pixc) {
        pixGetDimensions(pixc, &w, &h, &d);
        printf("pixc: %dx%d depth=%d\n", w, h, d);
        PIXCMAP *cc = pixGetColormap(pixc);
        if (cc) printf("  pixc cmap count: %d\n", pixcmapGetCount(cc));
        pixDestroy(&pixc);
    } else {
        printf("pixc NULL\n");
    }

    pixDestroy(&pix1);
    pixDestroy(&pix2);
    pixDestroy(&pix3);
    pixDestroy(&pix4);
    pixDestroy(&pixs);
    return 0;
}
EOF
